import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const SimpleDashboard = () => {
  const navigate = useNavigate();
  const [companyData, setCompanyData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadData = async () => {
      try {
        console.log('Dashboard: Loading data from localStorage...');
        const storedCompanyData = localStorage.getItem('companyData');
        console.log('Dashboard: Raw stored data:', storedCompanyData);

        if (!storedCompanyData) {
          console.log('Dashboard: No company data found, redirecting...');
          navigate('/');
          return;
        }

        const companyData = JSON.parse(storedCompanyData);
        console.log('Dashboard: Parsed company data:', companyData);

        // Enhance company data with dynamic calculations
        const enhancedCompanyData = enhanceCompanyData(companyData);
        setCompanyData(enhancedCompanyData);

        // Generate dynamic AI analysis if not present
        if (!enhancedCompanyData.ai_analysis) {
          const dynamicAIAnalysis = generateDynamicAIAnalysis(enhancedCompanyData);
          enhancedCompanyData.ai_analysis = dynamicAIAnalysis;

          // Update localStorage with enhanced data
          localStorage.setItem('companyData', JSON.stringify(enhancedCompanyData));
        }

        // Set risk analysis from AI results
        if (enhancedCompanyData.ai_analysis.risk_analysis) {
          setRiskAnalysis(enhancedCompanyData.ai_analysis.risk_analysis);
          console.log('Dashboard: AI Risk analysis set:', enhancedCompanyData.ai_analysis.risk_analysis);
        }

        // Set recommendation from loan analysis
        if (enhancedCompanyData.ai_analysis.loan_analysis) {
          setRecommendation({
            decision: enhancedCompanyData.ai_analysis.decision_result?.decision || 'Conditional Approval',
            loan_limit: enhancedCompanyData.ai_analysis.loan_analysis?.approved_loan_amount || 50000000,
            interest_rate: enhancedCompanyData.ai_analysis.loan_analysis?.interest_rate || 11.5,
            confidence_score: enhancedCompanyData.ai_analysis.decision_result?.confidence_score || 0.7
          });
          console.log('Dashboard: AI Loan analysis set:', enhancedCompanyData.ai_analysis.loan_analysis);
        }
      } catch (err) {
        console.error('Dashboard: Error loading data:', err);
        setError('Failed to load dashboard data: ' + err.message);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [navigate]);

  // Enhance company data with dynamic calculations
  const enhanceCompanyData = (data) => {
    const company = data.company || 'Unknown Company';
    const revenue = data.revenue || 0;
    const profit = data.profit || 0;
    const assets = data.assets || 0;
    const liabilities = data.liabilities || 0;

    // Generate company-specific hash for dynamic data
    const companyHash = company.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);

    // Calculate financial ratios
    const profitMargin = revenue > 0 ? (profit / revenue) * 100 : 0;
    const debtToEquity = (assets - liabilities) > 0 ? (liabilities / (assets - liabilities)) * 100 : 0;
    const returnOnAssets = assets > 0 ? (profit / assets) * 100 : 0;

    return {
      ...data,
      financial_ratios: {
        profit_margin: profitMargin,
        debt_to_equity: debtToEquity,
        return_on_assets: returnOnAssets
      },
      company_hash: companyHash,
      last_updated: new Date().toISOString()
    };
  };

  // Generate dynamic AI analysis based on company data
  const generateDynamicAIAnalysis = (companyData) => {
    const company = companyData.company || 'Unknown Company';
    const revenue = companyData.revenue || 0;
    const profit = companyData.profit || 0;
    const assets = companyData.assets || 0;
    const liabilities = companyData.liabilities || 0;
    const companyHash = companyData.company_hash || 0;

    // Calculate dynamic risk score based on financial metrics
    let riskScore = 50; // Base score

    // Profit margin impact
    const profitMargin = companyData.financial_ratios?.profit_margin || 0;
    if (profitMargin > 15) riskScore -= 20;
    else if (profitMargin < 5) riskScore += 25;
    else if (profitMargin < 10) riskScore += 10;

    // Debt to equity impact
    const debtToEquity = companyData.financial_ratios?.debt_to_equity || 0;
    if (debtToEquity > 100) riskScore += 20;
    else if (debtToEquity < 30) riskScore -= 10;

    // Size factor (larger companies get lower risk)
    if (revenue > 1000000000) riskScore -= 15; // > 1000 Cr
    else if (revenue > 100000000) riskScore -= 10; // > 100 Cr
    else if (revenue < 10000000) riskScore += 15; // < 10 Cr

    // Add some randomness based on company hash
    riskScore += (companyHash % 20) - 10;

    // Ensure score is within bounds
    riskScore = Math.max(20, Math.min(85, riskScore));

    // Determine risk category
    let riskCategory = 'Medium Risk';
    if (riskScore < 35) riskCategory = 'Low Risk';
    else if (riskScore > 65) riskCategory = 'High Risk';

    // Calculate loan amount based on risk and financials
    const maxLoanRatio = riskScore < 35 ? 0.4 : riskScore < 55 ? 0.25 : 0.15;
    const approvedLoanAmount = Math.floor(revenue * maxLoanRatio);

    // Calculate interest rate based on risk
    const baseRate = 8.5;
    const riskPremium = (riskScore - 50) * 0.15;
    const interestRate = Math.max(7.5, Math.min(16, baseRate + riskPremium));

    // Determine decision
    let decision = 'Conditional Approval';
    if (riskScore < 35 && profitMargin > 10) decision = 'Approve';
    else if (riskScore > 70 || profitMargin < 2) decision = 'Reject';

    // Generate risk factors
    const riskFactors = [];
    if (profitMargin < 5) {
      riskFactors.push({
        category: 'Financial',
        severity: 'High',
        description: 'Low profit margin indicates operational inefficiency',
        recommendation: 'Focus on cost optimization and revenue enhancement'
      });
    }
    if (debtToEquity > 80) {
      riskFactors.push({
        category: 'Leverage',
        severity: 'Medium',
        description: 'High debt-to-equity ratio increases financial risk',
        recommendation: 'Consider debt restructuring and equity infusion'
      });
    }
    if (riskScore > 60) {
      riskFactors.push({
        category: 'Credit',
        severity: 'High',
        description: 'Elevated credit risk requires additional collateral',
        recommendation: 'Request additional security guarantees'
      });
    }

    // Generate confidence score
    const confidenceScore = 0.6 + (Math.random() * 0.3); // 60-90%

    // Generate key factors
    const keyFactors = [
      `Profit margin of ${profitMargin.toFixed(1)}% impacts repayment capacity`,
      `Revenue size of ₹${(revenue/10000000).toFixed(1)}Cr provides business stability`,
      `Risk score of ${riskScore} indicates ${riskCategory.toLowerCase()} profile`,
      `Debt-to-equity ratio of ${debtToEquity.toFixed(1)}% affects financial leverage`
    ];

    return {
      risk_analysis: {
        risk_score: riskScore,
        risk_category: riskCategory,
        confidence_score: confidenceScore,
        key_factors: keyFactors
      },
      loan_analysis: {
        approved_loan_amount: approvedLoanAmount,
        interest_rate: interestRate,
        max_loan_ratio: maxLoanRatio,
        recommended_tenure: 60 // months
      },
      decision_result: {
        decision: decision,
        confidence_score: confidenceScore,
        key_factors: keyFactors,
        reasoning: `Based on comprehensive analysis of financial metrics, the company shows ${profitMargin > 10 ? 'strong' : profitMargin > 5 ? 'moderate' : 'weak'} profitability with ${riskCategory.toLowerCase()} profile. The approved loan amount considers the revenue base and risk parameters.`,
        recommended_actions: [
          'Monitor quarterly financial performance',
          'Maintain debt service coverage ratio above 1.5',
          'Submit regular compliance reports',
          'Provide quarterly business updates'
        ]
      },
      risk_factors: riskFactors
    };
  };

  const formatCurrency = (amount) => {
    if (!amount) return '₹0';
    if (amount >= 10000000) {
      return `₹${(amount / 10000000).toFixed(1)}Cr`;
    } else if (amount >= 100000) {
      return `₹${(amount / 100000).toFixed(1)}L`;
    } else {
      return `₹${amount.toLocaleString('en-IN')}`;
    }
  };

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f0f9ff' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ 
            width: '48px', 
            height: '48px', 
            border: '4px solid #e5e7eb', 
            borderTop: '4px solid #2563eb', 
            borderRadius: '50%', 
            animation: 'spin 1s linear infinite',
            margin: '0 auto 16px'
          }}></div>
          <p style={{ fontSize: '18px', color: '#4b5563' }}>Loading your credit analysis...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f0f9ff' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '48px', marginBottom: '16px' }}>⚠️</div>
          <h2 style={{ fontSize: '24px', fontWeight: 'bold', color: '#dc2626', marginBottom: '8px' }}>Error Loading Dashboard</h2>
          <p style={{ color: '#6b7280', marginBottom: '24px' }}>{error}</p>
          <button 
            onClick={() => window.location.reload()}
            style={{ 
              backgroundColor: '#2563eb', 
              color: 'white', 
